!function(r){function t(t){for(var i,n,o=t[0],u=t[1],m=t[2],s=0,g=[];s<o.length;s++)n=o[s],Object.prototype.hasOwnProperty.call(a,n)&&a[n]&&g.push(a[n][0]),a[n]=0;for(i in u)Object.prototype.hasOwnProperty.call(u,i)&&(r[i]=u[i]);for(c&&c(t);g.length;)g.shift()();return p.push.apply(p,m||[]),e()}function e(){for(var r,t=0;t<p.length;t++){for(var e,n=p[t],o=!0,u=1;u<n.length;u++)e=n[u],0!==a[e]&&(o=!1);o&&(p.splice(t--,1),r=i(i.s=n[0]))}return r}function i(t){if(n[t])return n[t].exports;var e=n[t]={i:t,l:!1,exports:{}};return r[t].call(e.exports,e,e.exports,i),e.l=!0,e.exports}var n={},a={20:0},p=[];i.m=r,i.c=n,i.d=function(r,t,e){i.o(r,t)||Object.defineProperty(r,t,{enumerable:!0,get:e})},i.r=function(r){"undefined"!=typeof Symbol&&Symbol.toStringTag&&Object.defineProperty(r,Symbol.toStringTag,{value:"Module"}),Object.defineProperty(r,"__esModule",{value:!0})},i.t=function(r,t){if(1&t&&(r=i(r)),8&t)return r;if(4&t&&"object"==typeof r&&r&&r.__esModule)return r;var e=Object.create(null);if(i.r(e),Object.defineProperty(e,"default",{enumerable:!0,value:r}),2&t&&"string"!=typeof r)for(var n in r)i.d(e,n,function(t){return r[t]}.bind(null,n));return e},i.n=function(r){var t=r&&r.__esModule?function(){return r.default}:function(){return r};return i.d(t,"a",t),t},i.o=function(r,t){return Object.prototype.hasOwnProperty.call(r,t)},i.p="";var o=window.webpackJsonp=window.webpackJsonp||[],u=o.push.bind(o);o.push=t,o=o.slice();for(var m=0;m<o.length;m++)t(o[m]);var c=u;p.push([48,0]),e()}({48:function(r,t,e){"use strict";e.r(t);var i=e(0);Object(i.a)("ru","army",e(49),e(1))},49:function(r){r.exports=JSON.parse('{"category":[{"name":"苏联","link":"ru_shortcut"},{"name":"陆战武器","link":"ru_army"},{"name":"自行炮车","link":"ru_army#ru_army_spv"}],"model":"BM-13型自行火箭炮车","description":"<h6>综述：</h6><p>BM-13型自行火箭炮车是二战苏军的一种强大的火力装备，它在1939年研制定型，在苏德战争开始后正式列装苏军部队；BM-13自行火箭炮车于1941年7月第一次参加作战，由于其火力凶猛，虽然命中准确度低，但火力覆盖面大，因此具有对密集德军进行大面积的打击，摧毁敌方防御工事和对敌方火力进行强力压制的能力，很受苏军的喜爱，在战争中为苏军的胜利发挥了极大的作用。苏军战士根据其出厂标记“K”将BM-13自行火箭炮车昵称为“喀秋莎”，从而也产生了一支著名的苏联歌曲“喀秋莎”。由于BM-13发射时火箭弹会发出一种独特而又震摄人心的声音，德军又称之为“斯大林管风琴”。</p><p>BM-13自行火箭炮车构造简单，制造成本很低，易于生产，1941年至1944年共生产了近7000辆。</p>","part1title":"系列型号","part1description":"","part1content":[{"image":"imgs/ru/army/ru_army_rltBM13_11.jpg","description":"<h6>BM-13型自行火箭炮车</h6><p>BM-13型自行火箭炮有8条滑轨，每条滑轨上下各悬挂着一枚132mm口径的火箭弹，一共16枚，在发射装置的控制下可进行单发，连发与齐发。</p><p>BM-13型自行火箭炮车可分为火箭发射器和承载车两个结构主体，火箭发射器为BM-13型；而承载车则会使用不同卡车底盘。</p><p><strong>BM-13型火箭发射器（弹）技术数据如下 ：</strong></p><p>火箭弹型号：M-13；口径：132mm，火箭弹重量：42.5kg，火箭弹长：1.42m；有效射程：8500m。</p><p>完成全部火箭弹的装填时间为5～10分钟，一次齐射只需7～10秒。</p><p><strong>其中使用苏制ZIL-151型卡车为底盘的火箭炮车技术数据如下：</strong></p><p>炮车长：5.25米，宽：2.3米，高：3.2米，重：5.73吨；</p><p>最高车速为50千米/小时，最大行程为180千米。</p>","caption":""}],"part2title":"战场上的BM-13型自行火箭炮车","part2description":"","part2content":[{"image":"imgs/ru/army/ru_army_rltBM13_21.jpg","description":"以奥斯汀K6（6X6）卡车底盘为承载体的BM-13型自行火箭炮车。","caption":""},{"image":"imgs/ru/army/ru_army_rltBM13_22.jpg","description":"以Studebaker US6（6X6）卡车底盘为承载体的BM-13型自行火箭炮车。","caption":""},{"image":"imgs/ru/army/ru_army_rltBM13_23.jpg","description":"以WOT-8（4X4）卡车底盘为承载体的BM-13型自行火箭炮车。","caption":""},{"image":"imgs/ru/army/ru_army_rltBM13_24.jpg","description":"以福特HH6（4X4）卡车底盘为承载体的BM-13型自行火箭炮车。","caption":""},{"image":"imgs/ru/army/ru_army_rltBM13_25.jpg","description":"1943年9月，东线苏联战场乌克兰顿涅茨克地区，苏军第4近卫火箭炮兵团的BM-13型自行火箭炮车进入发射阵地，苏军炮兵正在为火箭炮装填火箭弹，炮车底盘是ZIS-6卡车。","caption":""},{"image":"imgs/ru/army/ru_army_rltBM13_26.jpg","description":"接上图，1943年9月，东线苏联战场乌克兰顿涅茨克地区，隶属苏军第4近卫火箭炮兵团的BM-13型自行火箭炮车已在发射阵地作好开火准备。","caption":""},{"image":"imgs/ru/army/ru_army_rltBM13_27.jpg","description":"1943年夏天，东线苏联战场，苏军中央方面军一支BM-13火箭炮车部队正进入发射阵地作战斗准备，炮车底盘是Studebaker US6（6X6）卡车。","caption":""},{"image":"imgs/ru/army/ru_army_rltBM13_28.jpg","description":"1943年11月，东线苏联战场，2名苏军炮兵正在为一辆BM-13火箭炮车作发射准备，该炮车隶属苏军第84近卫火箭炮兵团，炮车底盘是雪佛兰G-7171（4X4）卡车。","caption":""},{"image":"imgs/ru/army/ru_army_rltBM13_29.jpg","description":"1944年夏天，正在东线白俄罗斯战场作战的一辆苏军BM-13火箭炮车，炮车底盘是Studebaker US6（6X6）卡车。","caption":""},{"image":"imgs/ru/army/ru_army_rltBM13_30.jpg","description":"1944年秋天，东线战场布达佩斯地区，多辆苏军BM-13火箭炮车正在对敌方阵地进行射击，炮车底盘是Studebaker US6（6X6）卡车。","caption":""},{"image":"imgs/ru/army/ru_army_rltBM13_31.jpg","description":"1945年3月，东线战场波美拉尼亚地区，苏军炮兵正在将M-13火箭弹装上BM-13火箭发射器轨道中，炮车底盘是Studebaker US6（6X6）卡车。","caption":""},{"image":"imgs/ru/army/ru_army_rltBM13_32.jpg","description":"1945年春天，东线苏联战场，苏军的BM-13火箭炮车正在进行发射，图中可清晰见到飞出发射器轨道的M-13火箭弹，该炮车底盘是Studebaker US6（6X6）卡车。","caption":""},{"image":"imgs/ru/army/ru_army_rltBM13_33.jpg","description":"1944年夏天，东线战场某地，一张苏军火箭炮兵与BM-13火箭炮车的合照，从站在中前方军官胸前挂满的勋章可知，这是一个立功的火箭炮班。","caption":""},{"image":"imgs/ru/army/ru_army_rltBM13_34.jpg","description":"据不完全统计，1942至1945年间，战损的苏军BM-13火箭炮车约1500辆，由于1941年无统计数字，因此实际战损数会更多些。此图为1941年10月，在东线苏联战场Mcensk地区，被德军第4装甲师缴获的一辆已战损的苏军BM-13火箭炮车。德军以此图来证明苏联当时说没有火箭炮被德军缴获是不真实的宣传。","caption":""}]}')}});